'use client';

import { usePreviewToast } from './PreviewToast';

import { useState } from 'react';
import WellnessTabs from './WellnessTabs';
import { HugeiconsIcon } from '@hugeicons/react';
import { FireIcon, DropletIcon, Moon02Icon, Dumbbell01Icon, WorkoutRunIcon, Layers01Icon, ChartIncreaseIcon, MoreVerticalIcon } from '@hugeicons/core-free-icons';

export default function WellnessActivity() {
  const notify = usePreviewToast();
  const [tab, setTab] = useState('Activity');
  const [water, setWater] = useState(1200);
  const [options, setOptions] = useState(false);
  const [resetKey, setResetKey] = useState(0);
  return (
    <div className="sc-wellness-demo">
      <div className="sc-wellness-shell">
        <div className="sc-wellness-content"><div hidden={tab !== 'Activity'} className="sc-wellness-grid">
          <div className="sc-health-card sc-health-calories"><h3><HugeiconsIcon icon={FireIcon} />Calories</h3><div className="sc-health-value"><p><strong>5,839</strong><span>kcal</span></p><svg className="sc-health-ring" viewBox="0 0 50 50" aria-label="Calorie goal 65 percent"><circle cx="25" cy="25" r="20" /><circle cx="25" cy="25" r="20" pathLength="100" strokeDasharray="65 100" /></svg></div></div>
          <button type="button" className="sc-health-card sc-health-water" onClick={() => { const next = water >= 2500 ? 1200 : Math.min(water + 250, 2500); setWater(next); notify(water >= 2500 ? 'Water tracker reset.' : `Water updated to ${next.toLocaleString('en-US')} ml.`); }} aria-label={`Water ${water} milliliters. Add 250 milliliters; reset at goal.`}><h3><HugeiconsIcon icon={DropletIcon} />Water</h3><div className="sc-health-value"><p aria-live="polite"><strong>{water.toLocaleString('en-US')}</strong><span>ml</span></p><svg className="sc-health-ring" viewBox="0 0 50 50" aria-hidden="true"><circle cx="25" cy="25" r="20" /><circle cx="25" cy="25" r="20" pathLength="100" strokeDasharray={`${water / 25} 100`} /></svg></div></button>
          <div className="sc-health-card sc-health-sleep"><h3><HugeiconsIcon icon={Moon02Icon} />Sleep</h3><div className="sc-health-value"><p><strong>7.30</strong><span>hrs</span></p><div className="sc-health-bars" aria-label="Weekly sleep trend"><i /><i /><i /><i /><i /><i /><i /></div></div></div>
          <div className="sc-health-card sc-health-weight"><h3><HugeiconsIcon icon={Dumbbell01Icon} />Weight</h3><div className="sc-health-value"><p><strong>92</strong><span>kg</span></p><svg className="sc-health-trend" viewBox="0 0 80 55" role="img" aria-label="Weekly weight trend"><path d="M2 48 C7 14 15 47 24 34 S32 5 40 10 S47 48 55 25 S66 34 76 26" /></svg></div></div>
        </div><WellnessTabs key={resetKey} tab={tab} /></div>
        <div className="sc-wellness-bottom"><nav className="sc-wellness-nav" aria-label="Wellness demo">
          {[{ name: 'Activity', icon: FireIcon }, { name: 'Fitness', icon: WorkoutRunIcon }, { name: 'Plans', icon: Layers01Icon }, { name: 'Progress', icon: ChartIncreaseIcon }].map(item => <button type="button" key={item.name} aria-pressed={tab === item.name} onClick={() => setTab(item.name)}><HugeiconsIcon icon={item.icon} /><span>{item.name}</span></button>)}
        </nav><button type="button" className="sc-wellness-more" aria-label="Demo options" aria-expanded={options} onClick={() => setOptions(!options)}><HugeiconsIcon icon={MoreVerticalIcon} /></button></div>
        {options && <div className="sc-wellness-options"><button type="button" onClick={() => { setWater(1200); setResetKey(value => value + 1); setTab('Activity'); setOptions(false); notify('Activity reset.'); }}>Reset demo activity</button></div>}
      </div>
    </div>
  );
}

'use client';

import { createContext, useCallback, useContext, useEffect, useRef, useState, type ReactNode } from 'react';
import { HugeiconsIcon } from '@hugeicons/react';
import { CheckmarkCircle02Icon } from '@hugeicons/core-free-icons';

const ToastContext = createContext<((message: string) => void) | null>(null);

export function usePreviewToast() {
  const notify = useContext(ToastContext);
  if (!notify) throw new Error('Component previews must be rendered inside PreviewToast.');
  return notify;
}

/** Shared by every preview. Use the hook for actions, or data-preview-toast on simple demo buttons. */
export default function PreviewToast({ children }: { children: ReactNode }) {
  const [toast, setToast] = useState<{ id: number; message: string } | null>(null);
  const sequence = useRef(0);
  const notify = useCallback((message: string) => {
    if (message.trim()) setToast({ id: ++sequence.current, message });
  }, []);

  useEffect(() => {
    if (!toast) return;
    const timer = setTimeout(() => setToast(current => current?.id === toast.id ? null : current), 2800);
    return () => clearTimeout(timer);
  }, [toast]);

  return <ToastContext.Provider value={notify}>
    <div className="sc-toast-boundary" onClick={event => {
      if (!(event.target instanceof Element)) return;
      const trigger = event.target.closest<HTMLElement>('[data-preview-toast]');
      if (trigger && event.currentTarget.contains(trigger)) {
        const message = trigger.dataset.previewToast;
        if (message) notify(message);
      }
    }}>
      {children}
      <div className="sc-toast-layer" role="status" aria-live="polite" aria-atomic="true">
        {toast && <div key={toast.id} className="sc-preview-toast"><HugeiconsIcon icon={CheckmarkCircle02Icon} aria-hidden="true" /><span>{toast.message}</span></div>}
      </div>
    </div>
  </ToastContext.Provider>;
}

'use client';

import { useId, useState } from 'react';
import { HugeiconsIcon } from '@hugeicons/react';
import { FireIcon, Dumbbell01Icon, WorkoutRunIcon, Moon02Icon, ChartIncreaseIcon } from '@hugeicons/core-free-icons';
import { usePreviewToast } from './PreviewToast';

const workouts = [
  { name: 'Cardio', title: 'Full Body Burn', minutes: 20, icon: FireIcon },
  { name: 'Strength', title: 'Build Your Strength', minutes: 30, icon: Dumbbell01Icon },
  { name: 'Yoga', title: 'Stretch & Restore', minutes: 15, icon: WorkoutRunIcon },
  { name: 'HIIT', title: 'Quick Energy Boost', minutes: 12, icon: ChartIncreaseIcon },
];
const plans = [
  { name: 'Weight Loss', weeks: 4, day: 12, icon: ChartIncreaseIcon },
  { name: 'Get Fit', weeks: 6, day: 8, icon: WorkoutRunIcon },
  { name: 'Build Muscle', weeks: 8, day: 5, icon: Dumbbell01Icon },
  { name: 'Stay Healthy', weeks: 4, day: 9, icon: Moon02Icon },
];

export default function WellnessTabs({ tab }: { tab: string }) {
  const notify = usePreviewToast();
  const id = useId();
  const [workout, setWorkout] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [plan, setPlan] = useState(0);
  const [period, setPeriod] = useState('30');
  const active = workouts[workout];
  const selected = plans[plan];
  const percent = Math.round(selected.day / (selected.weeks * 7) * 100);
  const monthly = period === '30';
  const dates = monthly ? ['Nov 10', 'Nov 17', 'Nov 24', 'Dec 1', 'Dec 8'] : ['Mon', 'Tue', 'Wed', 'Fri', 'Sun'];
  return <>
    <section hidden={tab !== 'Fitness'} className="sc-wellness-view" aria-label="Fitness">
      <div className="sc-fitness-banner">
        <h3>Today’s Workout</h3><p>{active.title}</p><span>{active.minutes} min</span>
        <div className="sc-fitness-dumbbell" aria-hidden="true"><i /><b /><i /></div>
        <button type="button" className="sc-fitness-play" aria-label={playing ? 'Pause demo workout' : 'Start demo workout'} aria-pressed={playing} onClick={() => { setPlaying(!playing); notify(playing ? 'Demo workout paused.' : `${active.title} selected — workout preview only.`); }}>{playing ? 'Ⅱ' : '▶'}</button>
      </div>
      <div className="sc-wellness-choices">
        {workouts.map((item, index) => <button type="button" key={item.name} aria-pressed={workout === index} onClick={() => { setWorkout(index); setPlaying(false); }}><HugeiconsIcon icon={item.icon} /><span>{item.name}</span></button>)}
      </div>
      <h4>Weekly Activity</h4>
      <div className="sc-fitness-week" role="img" aria-label="Weekly activity: Monday 12, Tuesday 20, Wednesday 25, Thursday 18, Friday 20, Saturday 12, Sunday 20 minutes">
        {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map((day, index) => <div key={day}><div><i style={{ height: `${[35, 60, 75, 50, 60, 35, 60][index]}%` }} /></div><span>{day}</span></div>)}
      </div>
    </section>
    <section hidden={tab !== 'Plans'} className="sc-wellness-view" aria-label="Plans">
      <header className="sc-wellness-view-header"><div><h3>Your Plan</h3><p>Get fitter with a plan that fits you.</p></div><button type="button" aria-label="Next demo plan" onClick={() => { const next = (plan + 1) % plans.length; setPlan(next); notify(`${plans[next].name} plan selected.`); }}>›</button></header>
      <div className="sc-wellness-plan">
        <h3>{selected.name}</h3><p>{selected.weeks} Weeks Plan</p>
        <div className="sc-wellness-target" aria-hidden="true"><i />↗</div>
        <span>Day {selected.day} of {selected.weeks * 7}</span>
        <div className="sc-wellness-plan-progress"><progress max="100" value={percent} aria-label={`${selected.name} plan completion`} /><strong>{percent}%</strong></div>
      </div>
      <h4>Other Plans</h4>
      <div className="sc-wellness-choices sc-wellness-plan-choices">{plans.map((item, index) => index !== plan && <button type="button" key={item.name} onClick={() => { setPlan(index); notify(`${item.name} plan selected.`); }}><HugeiconsIcon icon={item.icon} /><span>{item.name}</span></button>)}</div>
    </section>
    <section hidden={tab !== 'Progress'} className="sc-wellness-view sc-wellness-progress-view" aria-label="Progress">
      <header className="sc-wellness-view-header"><div><h3>Your Progress</h3><p>Track your wellness journey.</p></div><select aria-label="Progress period" value={period} onChange={event => setPeriod(event.target.value)}><option value="30">Last 30 Days</option><option value="7">Last 7 Days</option></select></header>
      <div className="sc-wellness-progress-chart">
        <svg viewBox="0 0 360 155" role="img" aria-label={`Sample weight change: ${monthly ? 'minus 3.2' : 'minus 0.8'} kilograms over ${period} days`}>
          <defs><linearGradient id={`${id}-wash`} x1="0" x2="0" y1="0" y2="1"><stop stopColor="#d97af7" stopOpacity=".35" /><stop offset="1" stopColor="#d97af7" stopOpacity=".02" /></linearGradient></defs>
          <path d={monthly ? 'M0 35 C20 0 50 48 88 38 S132 54 166 52 S205 67 238 64 S282 88 314 85 S348 88 360 104 L360 140 H0Z' : 'M0 28 C40 20 56 49 88 42 S140 61 166 59 S210 78 238 74 S310 96 360 110 L360 140 H0Z'} fill={`url(#${id}-wash)`} />
          <path d={monthly ? 'M0 35 C20 0 50 48 88 38 S132 54 166 52 S205 67 238 64 S282 88 314 85 S348 88 360 104' : 'M0 28 C40 20 56 49 88 42 S140 61 166 59 S210 78 238 74 S310 96 360 110'} fill="none" stroke="#bd42f4" strokeWidth="3" />
          <path d="M238 35V140M0 140H360" stroke="#eee5f0" /><circle cx="238" cy={monthly ? 64 : 74} r="7" fill="white" stroke="#a13cf0" strokeWidth="4" />
          <rect x="202" y="5" width="73" height="29" rx="10" fill="#9839ef" /><text x="238" y="25" textAnchor="middle" fill="white" fontSize="14">{monthly ? '-3.2' : '-0.8'} kg</text>
        </svg>
        <div className="sc-wellness-chart-dates">{dates.map(date => <span key={date}>{date}</span>)}</div>
      </div>
      <div className="sc-wellness-progress-stats">
        <div><HugeiconsIcon icon={ChartIncreaseIcon} /><p><strong>{monthly ? '-3.2' : '-0.8'} kg</strong><span>Weight</span></p></div>
        <div><HugeiconsIcon icon={FireIcon} /><p><strong>{monthly ? '-1,240' : '-310'}</strong><span>Calories</span></p></div>
        <div><HugeiconsIcon icon={Moon02Icon} /><p><strong>+{monthly ? '1.4' : '0.5'} hrs</strong><span>Sleep</span></p></div>
      </div>
    </section>
  </>;
}

export const wellness = {
  slug: 'wellness-activity',
  name: 'Wellness activity',
  category: 'Health · Dashboard',
  description: 'A gentle daily check-in for calories, hydration, sleep, and weight. Pastel metric cards and a floating navigation bar make your daily routine feel a little lighter.',
  designStory: "Each metric has its own gentle color, making the four cards easy to scan without competing for attention. Compact charts show the rhythm of a day, while the floating navigation keeps the daily routine within reach.",
  interactionHint: "Add water in Activity, choose a workout in Fitness, switch plans, or compare 7-day and 30-day progress. All figures are sample data; the workout control is a preview. Use the options menu to reset the demo.",
  stage: 'wellness',
};

import Component from './Preview';
import PreviewToast from './PreviewToast';
import '@fontsource-variable/plus-jakarta-sans';
import './styles.css';

/** Copy this entire folder and import this entry point. */
export default function WellnessActivity() {
  return <div className="sc-package-wellness-activity"><PreviewToast><Component /></PreviewToast></div>;
}

