}

@layer components {
  :where(.sc-package-wellness-activity) .sc-toast-boundary { @apply relative w-full; isolation:isolate; }
  :where(.sc-package-wellness-activity) .sc-toast-layer { @apply pointer-events-none absolute inset-0 z-50 grid place-items-center; padding:4%; }
  :where(.sc-package-wellness-activity) .sc-preview-toast { @apply flex items-center justify-center gap-2 rounded-2xl border border-white/15 bg-[#17131f]/90 px-4 py-3 text-center font-medium text-white shadow-sm backdrop-blur-md; max-width:min(100%,340px); font-size:clamp(10px,2.7cqw,14px); line-height:1.5; overflow-wrap:anywhere; animation:scToastLifecycle 2800ms cubic-bezier(.22,1,.36,1) both; }
  :where(.sc-package-wellness-activity) .sc-preview-toast svg { @apply size-4 shrink-0 text-[#c4b5fd]; }
  :where(.sc-package-wellness-activity) .sc-wellness-options { @apply absolute z-20 rounded-xl border border-[#e7e5e0] bg-white p-3 shadow-sm; bottom:20cqw; right:7cqw; font-size:2.5cqw; }
